INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65978212', 65978212, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BALAI TEKNIK PERKERETAAPIAN SURABAYA', 'PERAWATAN PENGEMBALIAN FUNGSI BANGUNAN STASIUN SUMOBITO KABUPATEN JOMBANG', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Jawa Timur, Kediri (Kab.)', 300000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', 'Bangunan Stasiun Sumobito memerlukan rehabilitasi akibat penurunan kondisi fungsi dan estetika yang terjadi secara bertahap seiring bertambahnya usia bangunan, pengaruh cuaca, serta tingginya intensitas operasional pelayanan penumpang setiap harinya. Beberapa elemen bangunan seperti plafon, atap, dinding, instalasi listrik, serta area teras menunjukkan indikasi kerusakan berupa pelapukan material, kebocoran, retak rambut, korosi pada komponen penunjang, dan penurunan kualitas finishing. Selain itu terdapat ketidaksesuaian terhadap standar keselamatan bangunan operasional perkeretaapian yang dapat berpotensi menimbulkan risiko terhadap pengguna jasa maupun petugas operasional. Kondisi eksisting tersebut tidak hanya mempengaruhi tampilan fisik bangunan, namun juga berdampak pada tingkat kenyamanan, keselamatan, serta kualitas pelayanan stasiun secara keseluruhan. Apabila tidak segera ditangani, kerusakan dapat berkembang menjadi kerusakan struktural yang membutuhkan biaya perbaikan lebih besar serta berpotensi mengganggu kelancaran operasional perjalanan kereta api. Oleh karena itu diperlukan kegiatan rehabilitasi bangunan stasiun guna mengembalikan fungsi bangunan agar memenuhi standar laik fungsi, meningkatkan keandalan aset negara, serta mendukung penyelenggaraan operasional perkeretaapian yang selamat, aman, dan andal.', 'a. Pekerjaan Persiapan; 1. Mobilitas. 2. Pengamanan area kerja. 3. Fasilitas sementara. b. Pekerjaan Indoor; 1. Perbaikan instalasi listrik. 2. Bongkar dan pasang plafon loby. 3. Peambahan gantungan plafon. 4. Pasang list plafon loby dan Finishing cat. 5. Pasang list plafon mushola dan Finishing cat. 6. Pasang list plafon toilet pria dan Finishing cat. c. Pekerjaan Outdoor. 1. Pemasangan alumunium foil. 2. Perbaikan waterproofing dag beton. 3. Pengecatan plafon. 4. Pengecatan list plafon. 5. Pengecatan ulang dinding. 6. Perbaikan dan tambal sulam genteng. 7. Bongkar dan pasang plafon outdor. 8. Penggantian lisplank. 9. Peninggian lantai teras. 10. Bongkar dan pasang granit teras.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2483338);
