INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65978915', 65978915, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MALIKUSSALEH', 'Pendukung Pelayanan Publik', 'Barang', 'Pengadaan Langsung', 'Aceh, Aceh Utara (Kab.)', 216090000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 (satu) Paket', 'Keperluan Penunjang PJP2U', 'Spesifikasi Pekerjaan Penunjang Pelayanan Jasa Penumpang Pesawat Udara (PJP2U) meliputi pelaksanaan kegiatan operasional dalam mendukung kelancaran, kenyamanan, dan keselamatan pelayanan kepada penumpang di bandar udara. Ruang lingkup pekerjaan mencakup pelayanan di area terminal seperti pemeriksaan dokumen perjalanan, bantuan proses check-in dan boarding, pengaturan antrean, pelayanan informasi kepada penumpang, serta pendampingan bagi penumpang berkebutuhan khusus. Selain itu, pekerjaan meliputi pengawasan ketertiban dan kenyamanan area pelayanan, koordinasi dengan maskapai, ground handling, dan unit operasional lainnya, serta penanganan keluhan atau permasalahan pelayanan sesuai prosedur yang berlaku. Personel wajib memastikan standar pelayanan minimum terpenuhi, menjaga sikap profesional dan ramah, serta melaksanakan tugas sesuai Standar Operasional Prosedur (SOP), ketentuan keselamatan dan keamanan penerbangan, serta peraturan perundang-undangan yang berlaku guna menjamin mutu pelayanan jasa penumpang secara optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2485971);
