INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65977773', 65977773, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MALIKUSSALEH', 'Pemeliharaan Fasilitas Sisi Darat', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Aceh, Aceh Utara (Kab.)', 181500000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 (satu) Paket', '1. Pemeliharaan Fasilitas Sisi Darat - Pemeliharaan Gedung Terminal - Pemeliharaan Gedung Operasional Bandara', 'Spesifikasi Pekerjaan Pemeliharaan Gedung meliputi kegiatan pemeliharaan rutin, berkala, dan perbaikan terhadap seluruh komponen bangunan agar tetap berfungsi dengan baik, aman, dan layak digunakan. Lingkup pekerjaan mencakup pemeriksaan dan perawatan struktur bangunan, perbaikan dinding, lantai, dan plafon, pengecatan ulang, pemeliharaan atap dan talang air, serta perbaikan pintu dan jendela. Selain itu dilakukan pemeliharaan instalasi mekanikal, elektrikal, dan plumbing (MEP) seperti panel listrik, instalasi penerangan, stop kontak, pompa air, jaringan air bersih dan air kotor, serta sistem drainase. Pekerjaan juga mencakup pembersihan area gedung dan lingkungan sekitar, penggantian komponen yang rusak, serta pengujian fungsi untuk memastikan seluruh fasilitas beroperasi sesuai standar keselamatan dan ketentuan teknis yang berlaku. Seluruh pekerjaan dilaksanakan sesuai spesifikasi teknis, standar keselamatan kerja (K3), dan ketentuan peraturan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2486423);
