INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65978706', 65978706, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Konsultan Penyusunan Dokumen Analisis Statistik, Visualisasi Data, dan Replikasi untuk Mendukung Rekomendasi Kebijakan Pembangunan Sosial dan Penanggulangan Kemiskinan TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 97794000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Melakukan pengumpulan, pengolahan, dan analisis data terkait isu sosial dan ekonomi untuk mendukung penyusunan rekomendasi kebijakan. 2. Menyusun visualisasi data dalam bentuk grafik, tabel, infografis, atau format lain sesuai kebutuhan analisis. 3. Menyediakan bahan paparan berisi hasil analisis statistik dan visualisasi data sesuai kebutuhan Staf Ahli Menteri. 4. Melakukan kunjungan daerah atau tinjauan lapangan untuk menggali informasi mengenai implementasi program, mengonfirmasi temuan kajian, serta melakukan diseminasi awal (bila diperlukan) terkait rekomendasi kebijakan di bidang sosial. 5. Menyusun laporan analisis data secara berkala, termasuk hasil temuan, koordinasi, serta rekomendasi berbasis data. 6. Mendokumentasikan metodologi, pendekatan analisis, dan kode replikasi yang digunakan dalam pengolahan data. 7. Melakukan transfer of knowledge atas hasil pekerjaan kepada tim sekretariat Staf Ahli Menteri Bidang Sosial dan Penanggulangan Kemiskinan Kementerian PPN/Bappenas untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal 8. Melaksanakan tugas lain yang relevan, sesuai arahan Staf Ahli Menteri Bidang Sosial dan Penanggulangan Kemiskinan, dalam rangka penyusunan dan penguatan kebijakan bidang sosial.', '1. Melakukan pengumpulan, pengolahan, dan analisis data terkait isu sosial dan ekonomi untuk mendukung penyusunan rekomendasi kebijakan. 2. Menyusun visualisasi data dalam bentuk grafik, tabel, infografis, atau format lain sesuai kebutuhan analisis. 3. Menyediakan bahan paparan berisi hasil analisis statistik dan visualisasi data sesuai kebutuhan Staf Ahli Menteri. 4. Melakukan kunjungan daerah atau tinjauan lapangan untuk menggali informasi mengenai implementasi program, mengonfirmasi temuan kajian, serta melakukan diseminasi awal (bila diperlukan) terkait rekomendasi kebijakan di bidang sosial. 5. Menyusun laporan analisis data secara berkala, termasuk hasil temuan, koordinasi, serta rekomendasi berbasis data. 6. Mendokumentasikan metodologi, pendekatan analisis, dan kode replikasi yang digunakan dalam pengolahan data. 7. Melakukan transfer of knowledge atas hasil pekerjaan kepada tim sekretariat Staf Ahli Menteri Bidang Sosial dan Penanggulangan Kemiskinan Kementerian PPN/Bappenas untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal 8. Melaksanakan tugas lain yang relevan, sesuai arahan Staf Ahli Menteri Bidang Sosial dan Penanggulangan Kemiskinan, dalam rangka penyusunan dan penguatan kebijakan bidang sosial.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2489617);
